import { MakeLogicType, actions, afterMount, kea, key, path, props, reducers } from 'kea'
import { loaders } from 'kea-loaders'
import posthog from 'posthog-js'

import { teamLogic } from 'scenes/teamLogic'

import { visionObservationsSignalReportsList } from '../generated/api'
import { ObservationSignalReportApi } from '../generated/api.schemas'

export interface ObservationSignalReportsLogicProps {
    observationId: string
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface observationSignalReportsLogicValues {
    signalReports: ObservationSignalReportApi[] | null
    signalReportsLoading: boolean
    signalReportsUnavailable: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface observationSignalReportsLogicActions {
    loadSignalReports: () => any
    loadSignalReportsFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadSignalReportsSuccess: (
        signalReports: ObservationSignalReportApi[] | null,
        payload?: any
    ) => {
        signalReports: ObservationSignalReportApi[] | null
        payload?: any
    }
    setSignalReportsUnavailable: () => {
        value: true
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface observationSignalReportsLogicMeta {
    key: string
}

export type observationSignalReportsLogicType = MakeLogicType<
    observationSignalReportsLogicValues,
    observationSignalReportsLogicActions,
    ObservationSignalReportsLogicProps,
    observationSignalReportsLogicMeta
>

/** Grouping runs after the scan finishes, so an empty list means "not grouped yet" as much as "never grouped". */
export const observationSignalReportsLogic = kea<observationSignalReportsLogicType>([
    path(['products', 'replay_vision', 'frontend', 'observations', 'observationSignalReportsLogic']),
    props({} as ObservationSignalReportsLogicProps),
    key((props) => props.observationId),

    actions({
        setSignalReportsUnavailable: true,
    }),

    reducers({
        // A failed read must not read as "no reports": the caller may simply lack inbox access.
        signalReportsUnavailable: [
            false,
            {
                setSignalReportsUnavailable: () => true,
                loadSignalReports: () => false,
            },
        ],
    }),

    loaders(({ props, actions }) => ({
        signalReports: [
            null as ObservationSignalReportApi[] | null,
            {
                loadSignalReports: async () => {
                    const teamId = teamLogic.values.currentTeamId
                    if (!teamId) {
                        return null
                    }
                    try {
                        return await visionObservationsSignalReportsList(String(teamId), props.observationId)
                    } catch (e) {
                        // Supplementary context on an already-rendered page: fail quiet, don't toast over it.
                        posthog.captureException(e)
                        actions.setSignalReportsUnavailable()
                        return null
                    }
                },
            },
        ],
    })),

    afterMount(({ actions }) => {
        actions.loadSignalReports()
    }),
])
